-- Disposable/rollback synthetic workflow verification. Never sends messages.
begin;
do $$<<bucket_check>>declare patient uuid;pu uuid;clinician uuid;caregiver uuid;plan uuid;loop_id uuid;ev uuid;ctx uuid;ctx2 uuid;pol uuid;k uuid;result uuid;expected jsonb;body jsonb;n integer;begin
 select id,user_id into patient,pu from public.patients where synthetic order by created_at limit 1;
 select user_id into clinician from private.memberships where patient_id=patient and role='clinician' and active limit 1;
 select user_id into caregiver from private.memberships where patient_id=patient and role='caregiver' and active limit 1;
 perform set_config('request.jwt.claim.sub',pu::text,true);
 perform public.record_patient_context(patient,'weight',now()-interval '2 days','{"value":70}','kg','Fictional source',null,'Initial weight',gen_random_uuid());
 perform public.record_patient_context(patient,'bp',now()-interval '2 days','{"systolic":120,"diastolic":80}','mmHg','Fictional source',null,'Initial BP',gen_random_uuid());
 perform public.record_patient_context(patient,'investigation',now()-interval '2 days','{"reference":"Fictional prior report reference"}','reference','Fictional source',null,'Initial reference',gen_random_uuid());
 k:=gen_random_uuid();ctx:=public.record_patient_context(patient,'hba1c',now()-interval '1 day','{"value":7.2}','%','Fictional source',null,'Initial manual record',k);
 if public.record_patient_context(patient,'hba1c',now()-interval '1 day','{"value":7.2}','%','Fictional source',null,'Initial manual record',k)<>ctx then raise exception 'Context replay duplicated';end if;
 ctx2:=public.record_patient_context(patient,'hba1c',now()-interval '1 day','{"value":7.1}','%','Fictional source',ctx,'Corrected transcription',gen_random_uuid());
 if not exists(select 1 from public.patient_context_entries where id=ctx) then raise exception 'Original context lost';end if;
 begin perform public.record_patient_context(patient,'weight',now(),'{"value":70}','mmHg','Source',null,'Invalid unit',gen_random_uuid());raise exception 'Invalid context accepted';exception when raise_exception then if sqlerrm='Invalid context accepted' then raise;end if;end;
 begin perform public.save_workflow_policy(patient,'{}',null,'Patient cannot configure',gen_random_uuid());raise exception 'Patient set policy';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',caregiver::text,true);
 begin perform public.record_patient_context(patient,'weight',now(),'{"value":70}','kg','Source',null,'Denied',gen_random_uuid());raise exception 'Caregiver wrote context';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',clinician::text,true);
 select id into pol from public.workflow_policy_versions where patient_id=patient order by created_at desc,id desc limit 1;
 pol:=public.save_workflow_policy(patient,'{"windows":{"medication":60,"meals":120,"glucose":null,"test":1440},"stale_hours":48,"overdue_hours":24}',pol,'Synthetic operational windows; not clinical thresholds',gen_random_uuid());
 begin perform public.save_workflow_policy(patient,'{"windows":{"medication":60,"meals":120,"glucose":null,"test":1440},"stale_hours":48,"overdue_hours":24}',null,'Stale editor',gen_random_uuid());raise exception 'Stale policy accepted';exception when raise_exception then if sqlerrm='Stale policy accepted' then raise;end if;end;
 body:=jsonb_build_object('source_note','Fictional weekly routine','timezone','UTC','items',jsonb_build_array(jsonb_build_object('domain','medication','label','Rollback weekly medication','cadence','weekly','weekdays',jsonb_build_array(extract(dow from now() at time zone 'UTC')::integer),'start_date',(now() at time zone 'UTC')::date,'end_date',(now() at time zone 'UTC')::date+14,'times',jsonb_build_array('00:00'))));
 plan:=gen_random_uuid();perform public.confirm_care_plan(patient,plan,body,'Checked fictional weekly routine');
 select count(*) into n from public.care_loops l join public.care_plan_items i on i.id=l.item_id where i.plan_id=plan;
 if n<>3 then raise exception 'Weekly generation expected 3, got %',n;end if;
 if private.generate_plan(plan)<>0 then raise exception 'Weekly generation duplicated';end if;
 if exists(select 1 from public.care_loops l join public.care_plan_items i on i.id=l.item_id where i.plan_id=plan and extract(dow from l.due_at at time zone 'UTC')<>extract(dow from now() at time zone 'UTC')) then raise exception 'Wrong weekday';end if;
 select l.id into loop_id from public.care_loops l join public.care_plan_items i on i.id=l.item_id where i.plan_id=plan and l.due_at<=now() limit 1;
 perform set_config('request.jwt.claim.sub',pu::text,true);
 perform public.log_care_activity(loop_id,'taken',jsonb_build_object('note','Fictional activity','activity_at',now()),gen_random_uuid());
 select id,jsonb_build_object('status',status,'note',details->>'note','occurred_at',occurred_at) into ev,expected from public.care_events where care_events.loop_id=bucket_check.loop_id;
k:=gen_random_uuid();result:=public.correct_care_activity(ev,expected,'missed','Corrected fictional activity',now(),'Recorded wrong status',k);
 if public.correct_care_activity(ev,expected,'missed','Corrected fictional activity',now(),'Recorded wrong status',k)<>result then raise exception 'Correction replay duplicated';end if;
 if (select state from public.care_loops where id=loop_id)<>'UNCONFIRMED' then raise exception 'Corrected missed activity stayed closed';end if;
 if not exists(select 1 from public.activity_corrections where id=result and before_value->>'status'='taken') then raise exception 'Correction lost original';end if;
 begin perform public.correct_care_activity(ev,expected,'taken','Stale update',now(),'Old editor',gen_random_uuid());raise exception 'Stale correction accepted';exception when raise_exception then if sqlerrm='Stale correction accepted' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',clinician::text,true);
 perform public.manage_care_loop(loop_id,'snooze',now()+interval '1 day','Synthetic reschedule identity check',gen_random_uuid());
 if private.generate_plan(plan)<>0 then raise exception 'Rescheduled weekly slot regenerated';end if;
 perform public.import_synthetic_glucose(patient,jsonb_build_array(jsonb_build_object('observed_at',now()+interval '1 hour','value',111,'unit','mg/dL','source_id','rollback-cutoff-fixture')));
 if (public.operational_snapshot(patient,now()-interval '7 days',now()+interval '1 day')#>>'{observations,0,observed_at}')::timestamptz>now() then raise exception 'Future observation hid latest available data';end if;
 if jsonb_array_length(public.operational_snapshot(patient,now()-interval '7 days',now()+interval '1 day')->'context')<2 then raise exception 'Context absent from summary';end if;
end$$;
-- Real authenticated role: no anonymous/direct write access, caregiver context hidden.
select set_config('request.jwt.claim.sub',(select user_id::text from private.memberships where role='caregiver' and active limit 1),true);
set local role authenticated;
do $$begin if exists(select 1 from public.patient_context_entries) or exists(select 1 from public.workflow_policy_versions) then raise exception 'Caregiver read clinical context';end if;
 begin insert into public.patient_context_entries default values;raise exception 'Direct write allowed';exception when insufficient_privilege then null;end;end$$;
rollback;
